import React from 'react';
import styles from './App.module.css';
import {Button} from './components/Button.jsx';
import {Field} from './components/Field.jsx';
export default function App(){return <main className={styles.shell}><header className={styles.header}><strong>Moss Lane Garden · Neighbors growing together</strong></header><h1>Make room for something good.</h1><p>Choose a volunteer shift at our community garden.</p><p>The sign-up flow is ready to implement.</p></main>}
.shell{max-width:1080px;margin:auto;padding:32px 24px}.header{border-bottom:1px solid var(--line);padding-bottom:20px;margin-bottom:40px}.shell h1{font-size:40px;line-height:1.1}@media(max-width:600px){.shell h1{font-size:32px}}
:root{--brand:#455C3C;--paper:#EDECE5;--ink:#263323;--muted:#777F70;--surface:#FFFFFF;--line:#C8CEBF;--highlight:#B6CC97;--radius:4px;--font:Arial,sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.5 var(--font)}button,input{font:inherit}:focus-visible{outline:3px solid var(--brand);outline-offset:4px}h1,h2,p{margin-top:0}
export const shifts=[{id:'morning',name:'Morning planting',date:'Saturday 24 October',time:'09:00–11:00',capacity:12,remaining:4},{id:'afternoon',name:'Path and bed care',date:'Saturday 24 October',time:'13:00–15:00',capacity:10,remaining:6},{id:'compost',name:'Compost crew',date:'Sunday 25 October',time:'10:00–12:00',capacity:8,remaining:0}];
import React from 'react';
import styles from './Shared.module.css';
export function Field({label,id,error,children,...props}){return <div className={styles.field}><label htmlFor={id}>{label}</label>{children||<input id={id} aria-invalid={Boolean(error)} aria-describedby={error?id+'-error':undefined} {...props}/>} {error&&<p id={id+'-error'} role="alert" className={styles.error}>{error}</p>}</div>}
import React from 'react';
import styles from './Shared.module.css';
export function Button({children,variant='primary',...props}){return <button className={variant==='secondary'?styles.secondary:styles.primary} {...props}>{children}</button>}
.primary,.secondary{font:inherit;font-weight:700;min-height:44px;padding:12px 20px;border:1px solid var(--brand);border-radius:4px;cursor:pointer}.primary{background:var(--brand);color:var(--paper)}.secondary{background:transparent;color:var(--brand)}.field{display:grid;gap:8px;margin-bottom:20px}.field label{font-weight:700}.field input,.field select,.field textarea{font:inherit;padding:12px;border:1px solid var(--muted);border-radius:4px;max-width:100%;width:100%;background:var(--surface);color:var(--ink)}.error{color:#9A321D;margin:0;font-size:14px}
import React from 'react';
import {createRoot} from 'react-dom/client';
import App from './App.jsx';
import './tokens.css';
createRoot(document.getElementById('root')).render(<App />);
